atives":[{"id":"01a218f9-3718-796a-818c-27d9668f3c28","description":"In cells","correct_answer":true},{"id":"01a218f9-3718-7c78-b36a-5f1677fde952","description":"In viruses","correct_answer":false},{"id":"01a218f9-3718-7844-90e6-de5b8432dc9b","description":"In the nucleus","correct_answer":false},{"id":"01a218f9-3718-749d-b2a1-aeef7a623826","description":"In blood plasma","correct_answer":false}]},{"id":"01a218f9-3718-7893-8b99-293ca8927a2e","locale":"en-US","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is an ion?","difficulty":1,"explanation":"An ion has an unequal number of protons and electrons, giving it a net charge; gaining or losing electrons creates that imbalance.","alternatives":[{"id":"01a218f9-3718-78e3-8cd2-0de21434c446","description":"An atom or molecule with an electric charge","correct_answer":true},{"id":"01a218f9-3718-7119-8eb9-edbd429163ae","description":"An atom with no electric charge","correct_answer":false},{"id":"01a218f9-3718-7708-8f8a-c382161ad073","description":"A chemical bond between two atoms","correct_answer":false},{"id":"01a218f9-3718-7c73-b715-b891e3f437d6","description":"A particle of light","correct_answer":false}]},{"id":"01a218f9-3718-78b6-896c-75bc66c3e66e","locale":"en-US","category":"01a21312-b489-7df1-b0c8-10e72868dcc8","question":"What is Parasitology the study of?","difficulty":1,"explanation":"Parasitology examines parasites and their relationships with the organisms they live on or in, called hosts.","alternatives":[{"id":"01a218f9-3718-71f6-93c4-9ffcc5cbd231","description":"parasites","correct_answer":true},{"id":"01a218f9-3718-7f15-aaab-6e0971987fa1","description":"crime","correct_answer":false},{"id":"01a218f9-3718-79da-a991-45410e663e62","description":"nutrition","correct_answer":false},{"id":"01a218f9-3718-7b45-afab-20e284ce4ef9","description":"the signification and application of words","correct_answer":false}]},{"id":"01a218f9-3718-745c-ad7a-0a9b0f233e93","locale":"en-US","category":"01a21312-